import sys


def reduce(t):
    changed = True
    while changed:
        changed = False
        for p in ("()", "[]", "{}", "<>"):
            if p in t:
                t = t.replace(p, "")
                changed = True
    return t


def main():
    s = sys.stdin.readline().strip()
    n = len(s)
    for i in range(1, n + 1):
        r = reduce(s[:i])
        if any(c in ")]}>" for c in r):
            print(i - 1)
            return
    print(-1 if reduce(s) == "" else n)


main()
